INSERT INTO `journal_encounter_section` VALUES (17841,'Overview','Adderis is a fearsome warrior, unleashing deadly electric attacks like his twofold strike |cFF2959D3|Hspell:1288049|h[Thunder and Lightning]|h|r.\n\nAspix is a relentless caster, creating powerful winds that damage and disrupt.\n\nAdderis and Aspix alternate being |cFF2959D3|Hspell:1310311|h[Storm Blessed]|h|r, which grants them immunity to damage.',2142,1,0,17842,17923,3,0,0,0,0,0,0,-1,69497),(17842,'Damage Dealers','$bullet;|cFF2959D3|Hspell:1310311|h[Storm Blessed]|h|r alternates between the sethrak duo which grants damage immunity.\n$bullet;|cFF2959D3|Hspell:1288049|h[Thunder and Lightning]|h|r is a two part attack, the first of which inflicts damage divided evenly between players hit.\n$bullet;|cFF2959D3|Hspell:1310712|h[Gale Force]|h|r violently pushes players backwards.',2142,2,17841,0,18503,3,0,0,0,0,0,2,-1,69497),(18196,'Section 10','',2144,7,18035,18197,0,2,0,0,266512,0,0,16,-1,69497),(18203,'Section 15','',2145,29,36417,0,0,2,0,0,1301253,0,0,0,-1,69497),(18205,'Corrupted Guardian','',2145,6,37180,37276,18513,1,145816,0,0,0,1,0,-1,69497),(18206,'Section 17','',2145,16,18205,0,36418,2,0,0,1300803,0,0,1,-1,69497),(18295,'Faithless Tormentor','',2145,25,37179,18298,0,1,80960,0,0,0,1,2,-1,69497),(18298,'','',2145,26,18295,0,0,2,0,0,1300714,0,0,4,-1,69497),(18513,'Twisted Hexxer','',2145,18,37180,18514,36989,1,84676,0,0,0,1,0,-1,69497),(18514,'','',2145,19,18513,0,36416,2,0,0,1302158,0,0,64,-1,69497),(18515,'Section 14','$[!8,23\n\nOn Mythic difficulty, multiple orbs of |cFF2959D3|Hspell:1300871|h[Corrupted Lifeforce]|h|r form.\n$]',2145,12,37276,37036,0,2,0,0,1300871,0,2,4096,0,69497),(34109,'Overview','Nymrissa Wavecaller creates an |cFF2959D3|Hspell:1257717|h[Alluring Bubble]|h|r within the grotto that lures nearby murlocs into her grasp. She then summons |cFF2959D3|Hspell:1258668|h[Swirling Whirlpools]|h|r to break the bubble, empowering murlocs within.',2849,1,0,35757,37201,3,0,0,0,0,0,0,-1,69497),(34110,'Tank','$bullet;|cFF2959D3|Hspell: 1282937|h[Iceblade Flurry]|h|r inflicts sustained damage to Nymrissa Wavecaller\'s current target.\n$bullet;|cFF2959D3|Hspell: 1257717|h[Alluring Bubble]|h|r attracts a large group of Bubblefin Shorerunners to rush toward the giant bubble.',2849,3,34109,0,36631,3,0,0,0,0,2,1,0,69497),(35024,'Overview','The Writhing Coil assaults its enemies relentlessly with |cFF2959D3|Hspell:1299940|h[Vindictive Onslaught]|h|r and its razor sharp |cFF2959D3|Hspell:1298949|h[Tail Scythe]|h|r.\n\nWhen the beast prepares to unleash |cFF2959D3|Hspell:1299053|h[Death Rattle]|h|r, Orweyna empowers players with |cFF2959D3|Hspell:1287798|h[Vine Grip]|h|r to |cFF2959D3|Hspell:1287811|h[Uncoil]|h|r the creature and clash with the serpents one by one.',2879,1,0,35025,36355,3,0,0,0,0,0,0,-1,69497),(35026,'Damage Dealers','$bullet; Interrupting |cFF2959D3|Hspell:1299053|h[Death Rattle]|h|r with |cFF2959D3|Hspell:1287798|h[Vine Grip]|h|r causes the creature to |cFF2959D3|Hspell:1287811|h[Uncoil]|h|r.\n$bullet; Damage inflicted while the Writhing Coil is |cFF2959D3|Hspell:1300612|h[Uncoiled]|h|r persists after |cFF2959D3|Hspell:1300686|h[Assimilation]|h|r.\n$bullet; |cFF2959D3|Hspell:1310974|h[Toxic Atrophy]|h|r reduces all players\' speed and damage done.',2879,3,35024,0,35027,3,0,0,0,0,0,2,-1,69497),(35058,'Overview','A mutated Zul\'jan unleashes his new power by |cFF2959D3|Hspell:1282403|h[Coalescing Venom]|h|r within The Coiled Altar. He wields twin axes that |cFF2959D3|Hspell:1299680|h[Sever]|h|r players and destroy Coalesced Venom.\n\nUpon Zul\'jan\'s defeat, Malacrass joins the fray. Malacrass haunts players with |cFF2959D3|Hspell:1285643|h[Dreadmarch]|h|r, creating Manifestations of Dread as it resolves. His casts of |cFF2959D3|Hspell:1286620|h[Soul Sever]|h|r hurt players and destroy any Manifestations of Dread in its blast.\n\nUpon defeat, Malacrass begins a ritual of |cFF2959D3|Hspell:1304032|h[Soulbinding]|h|r to revive Zul\'jan as his puppet, and claim what is rightfully his.',2883,1,0,35059,35584,3,0,0,0,0,0,0,-1,69497),(35060,'Healers','$bullet; |cFF2959D3|Hspell:1282487|h[Fangs of the Coiled Altar]|h|r and |cFF2959D3|Hspell:1298381|h[Defilement of the Coiled Altar]|h|r inflicts massive damage and healing absorbs to all players.\n$bullet; |cFF2959D3|Hspell:1282403|h[Coalesced Venom]|h|r explode into a |cFF2959D3|Hspell:1299838|h[Venom Rupture]|h|r when destroyed.\n$bullet; |cFF2959D3|Hspell:1282287|h[Venomfang]|h|r and |cFF2959D3|Hspell:1310882|h[Gloombomb]|h|r inflict heavy damage.',2883,3,35058,0,35061,3,0,0,0,0,0,4,-1,69497),(35062,'Hex Lord Malacrass','',2883,164,35403,36109,0,1,142140,0,0,0,1,0,-1,69497),(35063,'Zul\'jan','',2883,117,35403,36148,35062,1,142472,0,0,0,1,0,-1,69497),(35097,'Damage Dealers','$bullet;|cFF2959D3|Hspell:1289192|h[Caustic Deluge]|h|r ejects a salvo of globules which afflict players with |cFF2959D3|Hspell:1290336|h[Eternal Venom]|h|r when touched.\n$[14,17$bullet;|cFF2959D3|Hspell:1290516|h[Ravenous Feast]|h|r consumes applications of |cFF2959D3|Hspell:1290336|h[Eternal Venom]|h|r.$]\n$[15,16$bullet;High applications of |cFF2959D3|Hspell:1290336|h[Eternal Venom]|h|r kill players unless |cFF2959D3|Hspell:1290516|h[Ravenous Feast]|h|r consumes those applications.$]\n$bullet;|cFF2959D3|Hspell:1291404|h[Venomous Emergence]|h|r summons Spawns of Vexhul which will continuously target players with |cFF2959D3|Hspell:1291478|h[Corrosive Spit]|h|r.',2887,2,35096,0,35098,3,0,0,0,0,0,2,-1,69497),(35098,'Healers','$bullet;|cFF2959D3|Hspell:1289192|h[Caustic Deluge]|h|r ejects a salvo of globules which afflict players with |cFF2959D3|Hspell:1290336|h[Eternal Venom]|h|r when touched.\n$[14,17$bullet;|cFF2959D3|Hspell:1290516|h[Ravenous Feast]|h|r consumes applications of |cFF2959D3|Hspell:1290336|h[Eternal Venom]|h|r.$]\n$[15,16$bullet;High applications of |cFF2959D3|Hspell:1290336|h[Eternal Venom]|h|r kill players unless |cFF2959D3|Hspell:1290516|h[Ravenous Feast]|h|r consumes those applications.$]\n$bullet;|cFF2959D3|Hspell:1291404|h[Venomous Emergence]|h|r summons Spawns of Vexhul which will continuously target players with |cFF2959D3|Hspell:1291478|h[Corrosive Spit]|h|r.',2887,3,35096,0,35099,3,0,0,0,0,0,4,-1,69497),(35099,'Tanks','$bullet;|cFF2959D3|Hspell:1289993|h[Caustic Globules]|h|r form near the |cFF2959D3|Hspell:1289192|h[Caustic Deluge]|h|r target.\n$[14,17$bullet;|cFF2959D3|Hspell:1290516|h[Ravenous Feast]|h|r consumes applications of |cFF2959D3|Hspell:1290336|h[Eternal Venom]|h|r.$]\n$[15,16$bullet;High applications of |cFF2959D3|Hspell:1290336|h[Eternal Venom]|h|r kill players unless |cFF2959D3|Hspell:1290516|h[Ravenous Feast]|h|r consumes those applications.$]\n$bullet;If |cFF2959D3|Hspell:1288538|h[Stone Breaker]|h|r strikes no players, it instead strikes all players.',2887,4,35096,0,0,3,0,0,0,0,0,1,-1,69497),(35253,'Tanks','$bullet; |cFF2959D3|Hspell:1292034|h[Possession Barrage]|h|r inflicts damage based on the distance each barrage travels.\n$bullet;  Echoes of Jawae awaken during |cFF2959D3|Hspell:1292248|h[Soul Transfer]|h|r and provide Nekk\'zali with |cFF2959D3|Hspell:1289696|h[Tether of Awakening]|h|r.\n$bullet; Nek\'zali attacks her target with |cFF2959D3|Hspell:1284109|h[Hollowing Strikes]|h|r.',2888,4,35250,0,0,3,0,0,0,0,0,1,-1,69497),(35403,'Stage Three: Coiled Union','',2883,114,0,37191,0,0,0,0,0,0,0,0,-1,69497),(35405,'Section 9','',2871,29,0,0,35429,2,0,0,1282869,0,0,1,-1,69497),(35415,'Section 11','',2871,27,0,35416,35405,2,0,0,1285419,0,0,0,-1,69497),(35416,'Section 12','',2871,28,35415,0,0,2,0,0,1285447,0,0,0,-1,69497),(35419,'Section 13','',2871,23,0,35420,35415,2,0,0,1305959,0,2,8,0,69497),(35420,'Section 14','',2871,24,35419,0,36550,2,0,0,1287008,0,0,0,-1,69497),(35429,'Section 16','',2871,30,0,0,0,2,0,0,1285961,0,0,4,-1,69497),(35533,'Intermission: The Claimed Vessel','',2883,102,0,36658,35403,0,0,0,0,0,0,0,-1,69497),(35534,'Fragment of Malacrass','Fragments of Malacrass attempt to reunite with their new host.',2883,110,35583,35582,0,0,94426,0,0,0,1,4096,-1,69497),(35550,'Healers','$bullet; Every Blightscale Viper hatched inflicts |cFF2959D3|Hspell:1301268|h[Putrid Membrane]|h|r to all players.\n$bullet; |cFF2959D3|Hspell:1287265|h[Spectral Coils]|h|r inflicts damage to everyone that is reduced by the number of players at the impact location.',2895,3,35548,0,35551,3,0,0,0,0,0,4,-1,69497),(35564,'Section 10','',2895,57,35561,0,36425,2,0,0,1286834,0,0,4,-1,69497),(35565,'Section 8','',2895,59,35561,36739,35866,2,0,0,1286860,0,0,0,-1,69497),(35568,'Section 28','',2883,97,35599,36318,35613,2,0,0,1286895,0,2,8,0,69497),(35572,'Section 31','',2883,85,35599,35573,36317,2,0,0,1286441,0,2,4098,0,69497),(35573,'Spiteful Soulcoiler','',2883,86,35572,36853,0,0,146558,0,0,0,1,0,-1,69497),(35574,'Section 33','$[!16\n\nOn Mythic difficulty, interrupting Wail of Terror briefly reveals hidden Manifestations of Dread.$]',2883,88,35573,0,36833,2,0,0,1286399,0,0,4160,-1,69497),(35577,'Section 36','',2883,180,35062,35578,36719,2,0,0,1286918,0,0,18,-1,69497),(35578,'Section 37','',2883,181,35577,35579,0,2,0,0,1286912,0,0,0,-1,69497),(35579,'Section 38','',2883,182,35578,0,0,2,0,0,1286947,0,0,4,-1,69497),(35582,'Section 41','$[!16\nOn Mythic difficulty, stepping on a fragment increases damage all players take from Spirit Erasure by $1300665s1% for $1300665d.$]',2883,111,35534,0,35614,2,0,0,1287722,0,0,4096,-1,69497),(35583,'Section 42','',2883,108,35533,36663,36837,2,0,0,1304032,0,2,4096,0,69497),(35613,'Section 39','',2883,100,35599,0,36715,2,0,0,1307184,0,0,1,-1,69497),(35614,'Section 70','',2883,112,35534,0,0,2,0,0,1287718,0,0,0,-1,69497),(35615,'Section 71','',2883,195,35062,0,0,2,0,0,1307184,0,0,1,-1,69497),(35617,'Section 7','',2887,33,35618,0,36625,2,0,0,1288538,0,0,1,-1,69497),(35632,'Section 11','',2895,114,36171,36889,36284,2,143812,0,1289962,0,0,2,-1,69497),(35636,'Blightscale Viper','Fully gestated, the Blightscale Viper is a lethal predator.',2895,127,35632,36437,0,1,1429